journeys.priority={name:'关闭线上故障',icon:'flag',number:'04',title:'线上支付失败，恢复服务后通知用户并关单',person:'客服同事 · 故障处理台',input:'有用户反馈线上支付失败。请确认影响范围，找到值班负责人，跟进恢复，通知受影响用户，最后关闭工单。',goal:'负责人处理完成，监控连续恢复，82 位受影响用户收到通知，工单已关闭。',setup:'两边可读支付监控、值班表和工单，可通知值班负责人及受影响用户。修复由工程师执行；模型没有自行修复或上线代码的权限。',rule:'示例定级规则：生产支付失败率超过 5% 且影响超过 20 人，按 P1 处理。关闭前须有人工处理回执、连续 15 分钟失败率低于 1%、全部通知送达。',difference:'LLM 可以围绕故障目标生成查询和分配请求、撰写通知；Jev 在既定故障流程中选择优先级或负责人。工程师实际修复、监控核验和消息投递，两边都不能省略。',end:'支付服务已恢复 · INC-024 已关闭',proof:['负责人 PAY-07：处理确认＋ROLLBACK-01 成功','连续 15 分钟失败率：0.33% / 0.44% / 0.20%','恢复通知：82 / 82 已投递','工单 INC-024：closed · 10:28'],endReply:'支付服务异常已恢复。若仍有未完成订单，请先查看订单与扣款状态，避免重复支付；需要帮助可联系在线客服。',waitLabel:'监控恢复观察还不足 15 分钟',waitTitle:'负责人说修好了，还需要监控验证',waitContext:'负责人 PAY-07 已完成回滚，操作回执成功；目前只观察了 5 分钟，失败率 0.33%。另外两个窗口尚未产生。',waitProof:['负责人处理确认：已收到','ROLLBACK-01：success','恢复观察：5 / 15 分钟','工单 INC-024：observing，未关闭'],waitReply:'负责人已完成处理，目前进入恢复观察，尚未满足连续 15 分钟的恢复标准。工单仍保持处理中。',recovery:'模拟补齐 15 分钟恢复记录',waitAt:4,waitFor:'工程师处理（示例 10 分钟）＋恢复观察 15 分钟＋通知投递',steps:[
 phase('接收线上报障','客服反馈线上支付失败；尚未查询监控，原因未知。',activity('用户 → LLM','LLM 接收完整故障处理目标，请求先查事实。','核验支付异常、找负责人跟进修复，恢复后通知用户并关单。','下一步调用：query_payment_monitor。\n任务状态：开始排查，不能宣称已修复。','程序建立 INC-024，读取支付监控。',.65,230,43),activity('用户 → 程序 → Jev','程序将报障材料交给 Jev，决定先查什么。','问题：现在应做什么？\n选项：查支付监控 / 补充信息 / 关闭工单。','选择：查支付监控\n候选项概率：97% / 2% / 1%（演示）','程序建立 INC-024 并发起监控查询。',.14,215)),
 phase('核验影响范围','09:55–10:00：300 次支付、114 次失败，失败率 38%；82 位不同用户受影响。',activity('监控系统 → LLM','系统返回真实业务字段的模拟快照，模型读取影响。','支付监控快照 MON-01；过去 24 小时失败率基线 0.6%。','当前失败率 38%，明显高于基线；影响 82 人。\n服务仍未恢复。','平台保存监控快照及受影响用户集合，进入定级。',.6,460,49),activity('监控系统 → 编排程序','程序读取相同监控数据，按规则检查阈值。','MON-01：114 / 300 次失败；受影响用户 82 人；基线 0.6%。','阈值检查：38% > 5%，82 > 20。\n故障已确认，进入定级。','数值来自监控查询，不是 Jev 推测。')),
 phase('定级并找负责人','故障符合 P1；值班表中 PAY-07 负责支付链路且在线。',activity('LLM','LLM 根据故障规则和值班表返回处理方案。','选择 P1/P2/P3；选择 PAY-07 支付值班、WEB-03 前端、CS-02 客服。','优先级=P1；负责人=PAY-07。\n后续动作：通知负责人并等待接单。','平台核验值班状态，更新工单，发送故障通知。',.95,620,63),activity('Jev','程序分别提两个明确的问题：定级、选择负责人。','问题一：优先级 P1 / P2 / P3。\n问题二：负责人 PAY-07 / WEB-03 / CS-02。','返回两个选择：P1、PAY-07。\n选中项概率：98%、96%（演示）。','两项独立判断可一并提交；程序更新字段并发通知。',.21,565)),
 phase('接单并实际修复','PAY-07 于 10:02 接单；10:08 完成获批的配置回滚；10:09 提交处理确认。',activity('值班工程师处理','工程师排查并回滚错误配置，LLM 只读取处理记录。','人工记录：支付渠道配置错误；已获批从 r17 回滚至 r16。','接单回执 ACK-07；操作回执 ROLLBACK-01=success。\n负责人确认：已处理，等待监控验证。','实际修复由工程师完成；不能仅凭一句“已修好”关闭工单。'),activity('值班工程师处理','同一位模拟工程师执行处理，程序等待操作凭据。','相同的获批回滚记录、成功操作回执和人工确认。','接单回执 ACK-07；操作回执 ROLLBACK-01=success。\n负责人确认：已处理，等待监控验证。','Jev 不执行修复代码；程序启动恢复观察。')),
 phase('验证连续恢复','三个 5 分钟窗口：1/300=0.33%、2/450=0.44%、1/500=0.20%，均低于 1%。',activity('监控核验 → LLM','平台核验连续 15 分钟恢复，LLM 准备用户告知。','人工处理回执齐备，三个窗口均达标；尚未发送恢复通知。','下一步：发送恢复通知。\n当前还不能关闭：缺少用户通知回执。','系统冻结恢复快照，再按受影响用户集合发通知。',.65,490,43),activity('监控核验 → 编排程序','程序检查三个完整窗口，确定性规则无需模型。','要求：人工处理成功且连续三个窗口失败率 <1%。','恢复验证：通过。\n转入通知节点；关单条件仍缺通知回执。','保存监控证据，调用恢复通知流程。')),
 phase('通知并核验关单','82 位受影响用户：首次投递 80 人成功、2 人失败；重试后 82/82 成功。',activity('LLM 写通知 · 系统闭环','LLM 写恢复说明；平台只重试失败消息，证据齐备才关单。','根据已验证的恢复事实写通知，并提示先查订单状态、避免重复支付。','恢复通知批次 NOTICE-01：82/82 delivered。\n工单关闭回执：INC-024 closed，10:28。','同时保存处理记录、恢复快照和通知回执；送达不等于已读。',.9,510,78),activity('模板通知 · 系统闭环','程序填入恢复模板，只重试失败的 2 条，核验后关单。','恢复成功模板＋已记录的 82 位受影响用户＋失败重试标识。','恢复通知批次 NOTICE-01：82/82 delivered。\n工单关闭回执：INC-024 closed，10:28。','三项关闭条件都满足后才执行 close_ticket。'))
]};

function selectJourney(id){journey.id=journeys[id]?id:'support';journey.step=-1;journey.blocked=false;journey.confirmed=false;current=samples.find(s=>s.id===journey.id)||samples[0];current={...current,_journey:true};}
function journeyMetric(j,model){return j.steps.reduce((a,s)=>({time:a.time+s[model].time,input:a.input+s[model].input,output:a.output+s[model].output,calls:a.calls+(s[model].time?1:0)}),{time:0,input:0,output:0,calls:0});}
function journeyHeaders(){return `<div class="j-table-head"><span>同一件事的 6 个节点</span><div><b class="j-letter llm">L</b><span><strong>用 LLM 办</strong><small>生成方案与内容，平台执行</small></span></div><div><b class="j-letter jev">J</b><span><strong>用 Jev 办</strong><small>程序组织流程，模型做明确判断</small></span></div></div>`;}
function overviewRow(s,i){return `<div class="j-row"><button class="j-row-step" data-j-step="${i}"><span>${String(i+1).padStart(2,'0')}</span><strong>${s.title}</strong><small>展开这一步 ↗</small></button>${['llm','jev'].map(m=>`<article class="j-cell ${m}"><span class="j-actor">${s[m].actor}</span><p>${s[m].brief}</p><div class="j-evidence">${esc(s[m].result).replace(/\n/g,'<br>')}</div></article>`).join('')}</div>`;}
function journeyOverview(j){return `<section class="j-flow" aria-label="从用户需求到业务闭环">${journeyHeaders()}${j.steps.map(overviewRow).join('')}</section><div class="j-contrast"><b>这个案例，差别具体在哪？</b><p>${j.difference}</p></div>${journeyReceipt(j,true)}`;}
function blockedActivity(j,model){const a=activity(model==='llm'?'系统返回异常 → LLM':'系统返回异常 → 编排程序',model==='llm'?'LLM 读取未完成的回执，返回等待或重试建议。':'程序按状态规则进入等待或重试节点；确定的状态校验无需模型。',j.waitContext,model==='llm'?'建议动作：等待 / 重试失败部分。\n任务不能关闭，也不能告知全部完成。':'规则命中：缺少成功回执。\n保持任务未完成，只处理尚未成功的部分。','已经成功的操作不重复执行；恢复成功后继续核验。');a.unmetered=model==='llm';return a;}
function confirmationActivity(j,model){const refund=journey.id==='support';return activity('用户确认 · 尚未执行',refund?'客服先核对重复款，再确认退款。':'用户先核对时间和人员，再确认会议。',refund?'订单 O-1024；第二笔付款 P-882；金额 ¥99；退回原渠道。':'9 月 23 日 15:00–15:30；项目同步；你、林晓、陈瑜。',refund?'退款确认卡：待确认。\n尚未生成退款单，也未发生退款。':'会议确认卡：待确认。\n尚未创建会议，也未发送邀请。','点击下方模拟确认后，查看业务接口返回的受理凭据。');}
function detailModel(a,model){return `<article class="j-detail-model ${model}"><header><b class="j-letter ${model}">${model==='llm'?'L':'J'}</b><div><h3>${model==='llm'?'LLM 路径':'Jev 路径'}</h3><span>${a.actor}</span></div></header><p class="j-doing">${a.brief}</p><div class="j-detail-block"><span>① 这一步具体收到什么</span><p>${esc(a.request).replace(/\n/g,'<br>')}</p></div><div class="j-detail-block j-output"><span>② 具体返回什么</span><p>${esc(a.result).replace(/\n/g,'<br>')}</p></div><div class="j-detail-block"><span>③ 系统拿到结果后做什么</span><p>${esc(a.after)}</p></div><footer>${a.unmetered?'额外模型调用 · 用量和响应时间未预设':a.time?`本步模型响应 <b>${a.time.toFixed(2)} 秒</b><span>输入 ${a.input} Token${model==='llm'?' · 输出 '+a.output+' Token':''}</span>`:'本步由用户或业务程序完成，无模型调用'}<small>预设演示 · 不是实测</small></footer></article>`;}
function journeyWalk(j){const i=journey.step,s=j.steps[i],blocked=journey.blocked&&i>=j.waitAt,needsConfirm=i===3&&['support','tools'].includes(journey.id)&&!journey.confirmed;return `<section class="j-walk"><div class="j-stage-heading"><div><span>第 ${i+1} 步 / 共 6 步</span><h2>${s.title}</h2></div><span class="j-state ${blocked?'waiting':''}">${blocked?'尚未闭环':i===5?'查看完成凭据':i===3&&['support','tools'].includes(journey.id)&&!journey.confirmed?'等待确认（模拟）':'过程演示'}</span></div><div class="j-context"><b>当前业务事实</b><p>${blocked?j.waitContext:needsConfirm?'下面是待确认的执行卡片。用户确认后，平台才会提交实际操作；这里仅模拟这个交互。':s.context}</p></div><div class="j-detail-grid">${['llm','jev'].map(m=>detailModel(blocked?blockedActivity(j,m):needsConfirm?confirmationActivity(j,m):s[m],m)).join('')}</div>${i===5||blocked?journeyReceipt(j,!blocked):''}<div class="j-walk-controls"><button class="button secondary" data-j-action="prev" ${i===0?'disabled':''}>← 上一步</button><span>${i===3&&['support','tools'].includes(journey.id)&&!journey.confirmed?'这只是原型内的确认，不会操作真实系统。':blocked?'缺少成功回执，任务不能标为完成。':'两边都走完同一业务节点，再进入下一步。'}</span>${blocked?`<button class="button primary" data-j-action="recover">${j.recovery}</button>`:i===3&&['support','tools'].includes(journey.id)&&!journey.confirmed?`<button class="button primary" data-j-action="confirm">${journey.id==='support'?'模拟客服确认退款':journey.id==='tools'?'模拟确认并发送邀请':'继续执行（模拟）'}</button>`:i<5?'<button class="button primary" data-j-action="next">看下一步 →</button>':'<button class="button primary" data-j-action="overview">返回完整流程</button>'}</div></section>`;}
function journeyReceipt(j,complete){return `<section class="j-receipt ${complete?'':'waiting'}"><div class="j-receipt-title"><span>${complete?'✓':'…'}</span><div><small>${complete?'完成时，应该拿到这些凭据':'当前还缺少完成凭据'} · 模拟示例</small><h2>${complete?j.end:j.waitTitle}</h2></div><button class="text-link" data-j-action="evidence">查看记录 ↗</button></div><div class="j-proof-grid">${(complete?j.proof:j.waitProof).map(p=>`<div>${esc(p)}</div>`).join('')}</div><div class="j-final-message"><b>用户最后看到</b><p>“${esc(complete?j.endReply:j.waitReply)}”</p></div></section>`;}
renderSamples=function(){if(!current._journey||current.id!==journey.id)selectJourney(current.id);const j=journeys[journey.id];$('#main').classList.add('journey-main');$('#main').innerHTML=`<div class="j-page-heading"><div><span class="j-eyebrow">从一句需求，到事情办完</span><h1>选一件具体的事，看两边怎么做。</h1></div><button class="button secondary" data-j-action="own">${icon('plus')}换成我的材料</button></div><div class="j-case-tabs" aria-label="完整场景案例">${Object.entries(journeys).map(([id,c])=>`<button data-j-case="${id}" aria-pressed="${id===journey.id}" class="${id===journey.id?'selected':''}"><span>${c.number}</span><strong>${c.name}</strong>${icon(c.icon)}</button>`).join('')}</div><section class="j-brief"><div><span class="j-person">${j.person}</span><h2>${j.title}</h2><blockquote>“${esc(j.input)}”</blockquote></div><aside><span>怎样才算把事办完？</span><p>${j.goal}</p><button class="text-link" data-j-action="setup">两边需要先接入什么 ↗</button></aside></section><div class="j-controls"><div><button class="button ${journey.step===-1?'primary':'secondary'}" data-j-action="overview">看完整流程</button><button class="button ${journey.step>=0?'primary':'secondary'}" data-j-action="walk">${icon('play')}逐步体验</button><button class="text-link" data-j-action="metrics">时间与 Token ↗</button></div><label for="journey-branch">试试没办完时<select id="journey-branch"><option value="normal" ${!journey.blocked?'selected':''}>正常完成</option><option value="blocked" ${journey.blocked?'selected':''}>${j.waitLabel}</option></select></label></div><div class="j-step-nav" aria-label="跳转流程步骤">${j.steps.map((s,i)=>`<button data-j-step="${i}" aria-current="${i===journey.step?'step':'false'}" class="${i===journey.step?'active':''}"><span>${i+1}</span>${s.title}</button>`).join('')}</div><div id="journey-content">${journey.step===-1?journeyOverview(j):journeyWalk(j)}</div><p class="j-demo-note">所有流程、回执与数值均为预设演示。两条路径独立模拟，不会重复操作真实订单、日历或社区。</p>${footer}`;hydrateIcons();};
function journeyOwn(){const j=journeys[journey.id],q={support:['这笔订单应当如何处理？',['退重复款','补充材料','转人工']],tools:['应该选择哪个会议时段？',['15:00–15:30','17:00–17:30','需要补充信息']],moderation:['应当对这条帖子采取什么动作？',['发布','拦截','转人工']],priority:['本次故障应当采用哪个优先级？',['P1','P2','P3']]}[journey.id];formDraft={scenario:journey.id,title:j.name+' · 判断节点验证',input:j.input+'\n\n已查到的材料：'+j.steps[2].context,question:q[0],options:q[1].join('\n'),rule:j.rule,mode:'normal'};navigate('new');}
function showJourneyMetrics(){const j=journeys[journey.id],l=journeyMetric(j,'llm'),v=journeyMetric(j,'jev');showModal('模型返回快，不等于整件事马上办完',`<p class="modal-intro">下方是正常流程的预设用量。异常分支没有预设额外模型用量，不将其混入对比。单次响应、累计模型用时和业务闭环用时需要分开看。</p><table class="metric-table"><tr><th>正常路径 · 演示</th><th>LLM</th><th>Jev</th></tr><tr><td>首个模型结果</td><td>${j.steps.find(s=>s.llm.time).llm.time.toFixed(2)} 秒</td><td>${j.steps.find(s=>s.jev.time).jev.time.toFixed(2)} 秒</td></tr><tr><td>模型调用次数</td><td>${l.calls}</td><td>${v.calls}</td></tr><tr><td>累计模型响应时间</td><td>${l.time.toFixed(2)} 秒</td><td>${v.time.toFixed(2)} 秒</td></tr><tr><td>累计输入 Token</td><td>${l.input}</td><td>${v.input}</td></tr><tr><td>累计输出 Token</td><td>${l.output}</td><td>演示未提供；接入后读取实际用量</td></tr><tr><td>任务闭环总用时</td><td>未实测</td><td>未实测</td></tr></table><p class="modal-note">还要等待：${j.waitFor}。本例两条接法的模型调用次数、职责和输入量不同，不能据此计算模型速度倍数或成本优势。真正评测需记录每次调用、外部系统与人工等待，并固定版本和测试条件。</p>`,true);}
function showJourneySetup(){const j=journeys[journey.id];showModal('用户开始之前，平台准备了什么',`<p class="modal-intro">下面对比的是两种已接入业务工具的实现方式。用户只需提出需求；工具权限、接口和流程由平台预先配置。</p><div class="j-setup"><h3>共同的工具与规则</h3><p>${j.setup}</p><p>${j.rule}</p><h3>LLM 这边</h3><p>平台提供业务目标、操作规则和工具说明。模型可以生成结构化参数、工具调用请求和文案；程序校验后执行，再把结果交回模型。</p><h3>Jev 这边</h3><p>平台先定义业务流程，在需要判断的节点准备材料、问题和候选答案。Jev 返回选择，程序把选择映射到业务动作；通知使用预写模板。需要自由文本时，可以另接 LLM。</p><h3>什么负责证明“完成”？</h3><p>业务系统的状态和回执。确定的金额核对、状态检查、时间交集计算，不必每次交给模型。</p></div>`,true);}
function showJourneyEvidence(){const j=journeys[journey.id],done=!journey.blocked;showModal(done?'完成凭据 · 示例记录':'未完成凭据 · 示例记录',`<p class="modal-intro">这是预设的业务系统记录，不是真实查询结果。</p>${journeyReceipt(j,done).replace(/<button class="text-link" data-j-action="evidence">.*?<\/button>/,'')}<p class="modal-note">${j.rule}</p>`,true);}
function classicStory(){journey.step=stage==='trigger'?0:stage==='process'?3:5;updateJourney();}
const journeyOriginalNavigate=navigate;
navigate=function(next){if(next!=='samples')$('#main').classList.remove('journey-main');return journeyOriginalNavigate(next);};
function updateJourney(){renderSamples();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.jCase){selectJourney(b.dataset.jCase);updateJourney();}else if(b.dataset.jStep!==undefined){journey.step=Number(b.dataset.jStep);updateJourney();}else if(b.dataset.jAction){const a=b.dataset.jAction;if(a==='own')return journeyOwn();if(a==='metrics')return showJourneyMetrics();if(a==='setup')return showJourneySetup();if(a==='evidence')return showJourneyEvidence();if(a==='overview'){journey.step=-1;journey.blocked=false;}else if(a==='walk'){journey.step=0;journey.confirmed=false;journey.blocked=false;}else if(a==='next')journey.step=Math.min(5,journey.step+1);else if(a==='prev')journey.step=Math.max(0,journey.step-1);else if(a==='confirm'){journey.confirmed=true;}else if(a==='recover'){journey.blocked=false;journey.confirmed=true;journey.step=5;}updateJourney();}});
document.addEventListener('change',e=>{if(e.target.id==='journey-branch'){journey.blocked=e.target.value==='blocked';journey.step=journey.blocked?journeys[journey.id].waitAt:-1;updateJourney();}});
if(view==='samples')renderSamples();
if(document.modelContext?.registerTool){const lifetime=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'explore_complete_workflow',title:'查看具体场景的完整业务闭环',description:'在可见原型中切换退款、会议、帖子或故障的完整模拟流程，以及正常或未完成分支。不调用真实模型或业务系统。',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:['support','tools','moderation','priority']},step:{type:'integer',minimum:0,maximum:6,description:'0为简明对比，1至6为具体步骤'},branch:{type:'string',enum:['normal','blocked']}},required:['scenario'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>!['scenario','step','branch'].includes(k))||!journeys[input.scenario]||input.step!==undefined&&(!Number.isInteger(input.step)||input.step<0||input.step>6)||input.branch!==undefined&&!['normal','blocked'].includes(input.branch))throw new Error('请提供有效的场景、0–6步骤与分支');selectJourney(input.scenario);journey.blocked=input.branch==='blocked';journey.step=journey.blocked?journeys[journey.id].waitAt:(input.step??0)-1;if($('#modal').open)$('#modal').close();navigate('samples');return {scenario:journey.id,step:journey.step+1,branch:journey.blocked?'blocked':'normal',realActions:false};}},{signal:lifetime.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifetime.abort(),{once:true});}
